const x=$input.first().json.body;
const obj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SHA=/^[0-9a-f]{64}$/i;
const valid=(v,n)=>typeof v==='string'&&v.trim().length>0&&v.length<=n;
if(!obj(x)||Object.keys(x).sort().join(',')!=='agent_run_id,approved_sql,contract_version,correlation_metadata,principal'||
   x.contract_version!=='1'||!UUID.test(x.agent_run_id)||!valid(x.approved_sql,262144))throw Error('WITNESS_ENVELOPE_INVALID');
const p=x.principal,m=x.correlation_metadata;
if(!obj(p)||!UUID.test(p.id)||!UUID.test(p.organization_id)||!valid(p.profile,128)||
   Object.keys(p).some(k=>!['id','profile','organization_id'].includes(k)))throw Error('WITNESS_PRINCIPAL_INVALID');
if(!obj(m)||Object.keys(m).sort().join(',')!=='approval_binding_sha256,event,execution_request_id,request_id,route,source,timestamp'||
   !UUID.test(m.execution_request_id)||!SHA.test(m.approval_binding_sha256)||
   !UUID.test(m.request_id)||m.source!=='nextjs_bff'||m.event!=='execute_approved_shadow'||
   m.route!=='candidate_execute_approved_shadow_v1'||!valid(m.timestamp,64))throw Error('WITNESS_CORRELATION_INVALID');
return [{json:{shadow_witness_request:{contract_version:'1',agent_run_id:x.agent_run_id,approved_sql:x.approved_sql,principal:{id:p.id,profile:p.profile,organization_id:p.organization_id},correlation_metadata:{source:m.source,event:m.event,route:m.route,timestamp:m.timestamp,request_id:m.request_id,execution_request_id:m.execution_request_id,approval_binding_sha256:m.approval_binding_sha256}}}}];

const raw=$input.first().json;const src=$('Validate Approved SQL Witness Envelope').first().json.shadow_witness_request;
const obj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
if(![200,422].includes(raw.statusCode))throw Error('WITNESS_HTTP_NOT_ACCEPTED');
const d=obj(raw.body)?raw.body:raw;
const SHA=/^[0-9a-f]{64}$/i;
if(!obj(d)||d.contract_version!=='1'||d.agent_run_id!==src.agent_run_id||
   typeof d.run_id!=='string'||!d.run_id||!SHA.test(d.response_fingerprint)||
   !['success','rejected'].includes(d.status)||!obj(d.validation)||
   typeof d.requires_reapproval!=='boolean'||
   (raw.statusCode===200)!==(d.status==='success'))throw Error('WITNESS_EVIDENCE_INVALID');
if(d.validation.preflight?.executed===true||d.validation.security?.executed===true||
   d.validation.contract?.executed===true)throw Error('WITNESS_EXECUTED_FORBIDDEN');
if(d.status==='success'&&(
   d.validation.security?.status!=='approved'||
   d.validation.contract?.status!=='approved'||
   d.validation.preflight?.status!=='approved'||
   d.requires_reapproval))throw Error('WITNESS_GATES_NOT_APPROVED');
const proposal=typeof d.repaired_sql_proposal==='string'&&d.repaired_sql_proposal.trim().length>0;
if(proposal!==d.requires_reapproval)throw Error('WITNESS_REPAIR_PROVENANCE_INVALID');
return [{json:{contract_version:'1',agent_run_id:d.agent_run_id,
   execution_request_id:src.correlation_metadata.execution_request_id,
   run_id:d.run_id,status:d.status,response_fingerprint:d.response_fingerprint,
   requires_reapproval:d.requires_reapproval,
   validation:{security:d.validation.security?.status||'not_run',contract:d.validation.contract?.status||'not_run',preflight:d.validation.preflight?.status||'not_run'},
   real_sql_executed:false,financial_parity_proven:false}}];
